/* The workshop remains a memorial and a place where its kindness is practiced. */
(()=>{'use strict';
const Q=(title,prompt,choices,answer,hint)=>({kind:'choice',title,prompt,choices,answer,hint});
const O=(title,prompt,choices,answer,hint)=>({kind:'sequence',title,prompt,choices,answer,hint});
const puzzles={
 leather:Q('The last piece of leather','At the beginning of the tale, the shoemaker has enough leather for just one pair. What does he do before going to bed?',['Cuts the leather and lays it ready for morning','Throws his tools away','Buys a factory'],0,'He prepares the leather even though his money is almost gone.'),
 firstnight:O('Remember the first night','Reenact the work of that evening: cut the leather, lay it on the bench, then rest. This memory does not move the real clock.',['Rest','Cut leather','Lay pieces on bench'],[1,2,0],'The shoemaker prepares the pieces before he goes to bed.'),
 twopairs:Q('The first customer','A customer pays well for the beautifully made shoes. The shoemaker can now buy enough leather for how many pairs?',['Two pairs','One hundred pairs','No more shoes'],0,'The next night begins with leather for two pairs.'),
 curtain:Q('Who works at midnight?','The shoemaker and his wife hide behind a curtain and see two little elves finishing the shoes. What do they decide?',['Thank the helpers with clothes and shoes','Demand that the elves stay forever','Sell the elves to the customer'],0,'The couple responds with gratitude.'),
 preserve:Q('The original workbench','The shoemaker’s bench is worn smooth by years of work. How should its history be preserved?',['Strip away every old mark','Clean gently and preserve the tool marks','Replace it with a new bench'],1,'The marks are part of the object’s history.'),
 last:O('Restore the wooden last','The conservation card says: inspect the wood, brush loose dust, then support it in its case.',['Brush loose dust','Support in case','Inspect wood'],[2,0,1],'Inspect before cleaning. Support the object after cleaning.'),
 label:Q('Write an honest exhibit label','The couple thanked the elves with clothes and shoes. What belongs on the label?',['The helpers were paid with kindness and freedom','The elves were forced to stay forever','The shoemaker worked entirely alone'],0,'Remember the gifts that allowed the helpers to go freely.'),
 garment:O('Make a tiny gift','The elf-sized coat needs a pattern, joined panels, and finished edges—in that order.',['Finish edges','Cut pattern','Join panels'],[1,2,0],'The cloth needs its shape before the panels can be joined.'),
 gift:Q('A gift beneath the branches','Where should the gifts wait for the woodland helpers?',['In a locked cage','On a welcoming shelf, with no demand for work','Behind a sign demanding repayment'],1,'A thank-you should leave the recipient free.'),
 rune:O('Learn the silver-thread charm','The teaching slate reads Moon → Needle → Leaf → Moon.',['Leaf','Moon','Needle'],[1,2,0,1],'The charm returns to the Moon at its end.'),
 mend:Q('Magic that respects its material','A seam is sound except for one loose stitch. Choose your repair.',['Burn away the whole boot','Support the seam and replace the loose stitch','Hide the damage under paint'],1,'Repair the fault without damaging sound work.'),
 memory:Q('The memorial’s promise','What does this memorial honor?',['Only the price of famous shoes','The shoemaker, his partner, the helpers, and kindness carried forward','Only a royal family’s possessions'],1,'Many hands made the story possible.'),
 lantern:O('Light a remembrance lantern','The keeper asks you to choose a name, place the light safely, then share the memory.',['Share memory','Choose a name','Place light safely'],[1,2,0],'Remember the person before arranging the tribute.'),
 portrait:O('Care for a family portrait','The conservator’s plan is inspect, support the frame, then display away from harsh sunlight.',['Display in gentle light','Inspect','Support frame'],[1,2,0],'Protect the original before returning it to display.'),
 consent:Q('Let the family speak','A sibling wants a quiet reunion. What should the memorial record?',['Their choice and the words they offer','A dramatic story they did not agree to','Private details taken without permission'],0,'The person whose story it is has a voice.'),
 waylight:O('The Waylight constellation','Trace Star → River → Oak → Star on the enchanted map.',['Oak','Star','River'],[1,2,0,1],'Start and finish at the Star.'),
 bridge:Q('A lantern for the crossing','Where will a guiding light help a traveler most?',['At the marked safe crossing','In the deepest water','Behind a locked door'],0,'A guide should lead someone onto a safe route.'),
 bloom:O('The Bloomcall spell','Keeper Willow teaches Soil → Seed → Water → Light.',['Water','Light','Soil','Seed'],[2,3,0,1],'Start with a place for roots. Finish with light.'),
 share:Q('Let the garden thrive','The moonflowers bloom brightly. What should you leave?',['Nothing: harvest every flower','Plenty for pollinators and the next visitor','Only bare roots'],1,'A living gift keeps growing.'),
 quilt:O('The kingdom’s memory quilt','The hall’s work card reads: choose cloth, stitch the patches, then bind the edge.',['Bind edge','Choose cloth','Stitch patches'],[1,2,0],'The individual pieces come before their shared border.')
};
const step=(district,room,puzzle,text)=>({district,room,puzzle,text});
const activities=[
{id:'originaltale',title:'Live the Original Shoemaker’s Tale',reward:35,prize:'The first pair keepsake',steps:[step('workshop','originalShop','leather','Prepare the last piece of leather.'),step('workshop','originalShop','firstnight','Remember the first magical night.'),step('workshop','originalShop','twopairs','Welcome the first customer.'),step('workshop','originalShop','curtain','Discover who works behind the curtain.'),step('workshop','originalShop','garment','Make little clothes for the elves.'),step('workshop','originalShop','gift','Leave the gifts and let the helpers go freely.')]},
{id:'heirloom',title:'Restore the First Wooden Last',reward:24,prize:'Conservator’s silver pin',steps:[step('workshop','originalShop','preserve','Inspect the shoemaker’s original bench.'),step('workshop','originalShop','last','Conserve the first wooden shoe last.'),step('workshop','originalShop','label','Write the exhibit’s dedication.')]},
{id:'gifts',title:'Little Clothes for the Helpers',reward:26,prize:'Tiny embroidered coat',steps:[step('workshop','originalShop','garment','Sew a gift at the apprentice bench.'),step('forest','owlTreehouse','gift','Leave your thank-you at Aurelin’s story shelf.')]},
{id:'mending',title:'The Silver-Thread Enchantment',reward:28,prize:'Mending-light charm',spell:'mending',steps:[step('academy','spellAtelier','rune','Learn the moon-and-needle rune.'),step('workshop','originalShop','mend','Use a careful repair to anchor the charm.')]},
{id:'lantern',title:'A Light for Every Hand',reward:22,prize:'Memorial lantern',steps:[step('library','memoryHall','memory','Choose the memorial’s promise.'),step('festival','lantern','lantern','Light a tribute at the pavilion.')]},
{id:'portraits',title:'The Portraits Given Back',reward:25,prize:'Family portrait ribbon',steps:[step('library','memoryHall','portrait','Conserve an old family portrait.'),step('capital','manor','consent','Ask how the family wants its story told.')]},
{id:'waylight',title:'The Road of Little Stars',reward:28,prize:'Waylight star',spell:'waylight',steps:[step('academy','spellAtelier','waylight','Trace the guiding constellation.'),step('forest','well','bridge','Choose a safe place for its first light.')]},
{id:'bloom',title:'Moonflowers That Remember',reward:24,prize:'Bloomcall seed',spell:'bloom',steps:[step('academy','spellAtelier','bloom','Practice the growing spell.'),step('gardens','garden','share','Leave a living gift in the gardens.')]},
{id:'quilt',title:'A Quilt for the Whole Kingdom',reward:30,prize:'Community memory quilt',steps:[step('market','merchant','gift','Ask for cloth given freely.'),step('workshop','originalShop','quilt','Sew the community’s patches together.'),step('library','memoryHall','consent','Let every contributor choose their story.')]}
];
const exhibits=[['bench','The original workbench','Its worn surface preserves the work of the shoemaker and his partner. The bench remains furnished with lasts, leather, and hand tools.'],['shoes','The elves’ thank-you clothes','The couple made little clothes and shoes to thank the elves. The gifts honored the helpers’ freedom as well as their skill.'],['apron','The partner’s apron','The memorial remembers both people who kept this home and workshop. Their kindness made room for wonder.'],['thread','The hand-sewing tools','Awls, needles, linen thread and wooden lasts remain at the bench. The shoemaker cut the leather here before the helpers came at night.'],['portraits','The hiding curtain','Behind a curtain, the shoemaker and his wife watched two little elves making the shoes. They decided to thank them with little clothes and shoes.'],['hearth','The welcome by the hearth','The chairs, supper things, and warm hearth remain in place. This is a home whose story is still being lived.']];
function ensure(s){if(!s.cityHeritage||typeof s.cityHeritage!=='object'||Array.isArray(s.cityHeritage))s.cityHeritage={};const h=s.cityHeritage;for(const key of ['progress','completed','spells'])if(!h[key]||typeof h[key]!=='object'||Array.isArray(h[key]))h[key]={};if(!Array.isArray(h.exhibits))h.exhibits=[];if(typeof h.magicOn!=='boolean')h.magicOn=true;return h}
function current(s,id){const a=activities.find(a=>a.id===id);if(!a)return null;const h=ensure(s);return{activity:a,index:h.progress[id]||0,step:a.steps[h.progress[id]||0],complete:!!h.completed[id]}}
function at(station,w){return !!station&&!!w&&station.district===w.district&&station.room===w.room&&!w.porch}
function check(id,value){const p=puzzles[id];return !!p&&(p.kind==='sequence'?Array.isArray(value)&&value.length===p.answer.length&&value.every((n,i)=>n===p.answer[i]):value===p.answer)}
function answer(s,id,value,w){const i=current(s,id),h=ensure(s);if(!i?.step||!at(i.step,w))return{ok:false,reason:'Visit the current activity’s room first.'};value=globalThis.EldoriaPromiseModel?.guide(s,puzzles[i.step.puzzle],value)??value;if(!check(i.step.puzzle,value))return{ok:false,reason:puzzles[i.step.puzzle].hint};h.progress[id]=i.index+1;if(h.progress[id]<i.activity.steps.length)return{ok:true,next:true};h.progress[id]=0;const first=!h.completed[id];h.completed[id]=true;if(i.activity.spell)h.spells[i.activity.spell]=true;if(first){s.coins+=i.activity.reward;if(s.cityLife){s.cityLife.xp+=20;if(!s.cityLife.collection.includes(i.activity.prize))s.cityLife.collection.push(i.activity.prize)}}return{ok:true,title:i.activity.title+' complete',coins:first?i.activity.reward:0,prize:first?i.activity.prize:null,spell:i.activity.spell,practice:!first}}
function examine(s,id,w){if(!at({district:'workshop',room:'originalShop'},w)||!exhibits.some(e=>e[0]===id))return{ok:false};const h=ensure(s);if(!h.exhibits.includes(id))h.exhibits.push(id);return{ok:true,exhibit:exhibits.find(e=>e[0]===id)}}
globalThis.EldoriaHeritageModel={puzzles,activities,exhibits,ensure,current,at,check,answer,examine};
})();
